  ('gs-satt-board-jessore-2020-mcq-029', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p62', 'কোন সমস্যার কারণে মনির সাহেব বুকে তীব্র ব্যথা অনুভব করেন ?', 'mcq', '{"ক":"হার্ট ফেইলিউর","খ":"হার্ট অ্যাটাক","গ":"হার্ট স্ট্রোক","ঘ":"হার্ট ব্লক"}'::jsonb, 'ঘ', 1, false, 'gs-satt-board-jessore-2020-mcq', false, 'board-mcq', null, 'মনির সাহেব বুকে তীব্র ব্যথা নিয়ে ডাক্তারের শরণাপন্ন হলে ডাক্তার কিছু পরীক্ষা করতে বলেন। পরীক্ষাতে ডাক্তার তার হৃৎপিণ্ডে রক্তের অস্বাভাবিক প্রবাহ পান এবং সেই সাথে রক্তে অতিরিক্ত গ্লুকোজের উপস্থিতি লক্ষ করেন ।', 'jessore', 2020, true),
  ('gs-satt-board-jessore-2020-mcq-030', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p62', 'রক্তে উল্লেখিত পদার্থের অতিরিক্ত উপস্থিতি নিয়ন্ত্রণে প্রযোজ্য হলো- i. শৃঙ্খলা মেনে চলা ii. নিয়মিত প্রস্রাব পরীক্ষা iii. শ্বেতসারযুক্ত খাদ্য গ্রহণ নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'gs-satt-board-jessore-2020-mcq', false, 'board-mcq', null, 'মনির সাহেব বুকে তীব্র ব্যথা নিয়ে ডাক্তারের শরণাপন্ন হলে ডাক্তার কিছু পরীক্ষা করতে বলেন। পরীক্ষাতে ডাক্তার তার হৃৎপিণ্ডে রক্তের অস্বাভাবিক প্রবাহ পান এবং সেই সাথে রক্তে অতিরিক্ত গ্লুকোজের উপস্থিতি লক্ষ করেন ।', 'jessore', 2020, true),
